#!/bin/bash
# main: standards + spec. feature/greet: greet.js that breaks one standard (no JSDoc)
# and misses one requirement (no throw on an empty name), plus a generated file the
# standards say not to report.
set -e
git init -q -b main
git config user.email eval@example.com
git config user.name eval
mkdir -p docs dist
cat > CODING_STANDARDS.md <<'STD'
# Coding standards

- Every exported function has a JSDoc comment stating its parameters and return value.
- Functions validate their string arguments and throw a `TypeError` on an empty string.

## Do not report

- Anything under `dist/`: generated by the bundler, never edited by hand.
STD
cat > docs/spec-greet.md <<'SPEC'
# Spec: greet

- R1. `greet(name)` returns the string `Hello, <name>!`.
- R2. `greet` throws a `TypeError` when `name` is an empty string.
SPEC
git add -A
git commit -qm "add standards and greet spec"
git switch -qc feature/greet
cat > greet.js <<'JS'
function greet(name) {
  return "Hello, " + name + "!";
}

module.exports = { greet };
JS
printf 'var x=1;function g(n){return"Hello, "+n+"!"}\n' > dist/bundle.js
git add -A
git commit -qm "add greet"
